$action=$_POST['action']??null;$sid=(int)($_GET['simulation']??($_POST['simulation_id']??0));
if($_SERVER['REQUEST_METHOD']==='POST'){
    try{
        AuthService::requireCsrf();
        if($action==='create'){
            $plotCode=trim((string)($_POST['plot_code']??'CONCEALED_FAILURE'));
            $controllers=is_array($_POST['controllers']??null)?$_POST['controllers']:[];$sid=SimulationService::create($plotCode,(int)($_POST['duration_seconds']??300),$controllers);
            header('Location: ?simulation='.$sid);exit;
        }
        if($action==='start'){SimulationService::start($sid);CharacterAutomationService::process($sid);header('Location: ?simulation='.$sid);exit;}
        if($action==='advance'){SimulationService::advance($sid,(int)($_POST['seconds']??30));CharacterAutomationService::process($sid);header('Location: ?simulation='.$sid);exit;}
        if($action==='decide'){BehaviorService::chooseControlled($sid,(int)$_POST['decision_id'],(string)$_POST['option_code']);CharacterAutomationService::process($sid);header('Location: ?simulation='.$sid);exit;}
    }catch(Throwable$e){$error=$e->getMessage();}
}
if($sid>0){try{CausalService::reconcile($sid);StateSyncService::reconcile($sid);DynamicOpportunityService::reconcile($sid);CharacterAutomationService::process($sid);ResolutionService::refresh($sid);}catch(Throwable$e){$error=($error??'').(($error??'')?' | ':'').$e->getMessage();}}
$plots=[];$rolesByPlot=[];
try{$pq=db()->query('SELECT code,title,archetype,genre,setting_name,max_players,max_npcs FROM plots WHERE status="active" ORDER BY title');$plots=$pq->fetchAll();$rq=db()->query('SELECT p.code,pr.role_code,pr.role_type,pr.name,pr.slot_no FROM plot_roles pr JOIN plots p ON p.plot_id=pr.plot_id WHERE p.status="active" AND pr.simulation_active=1 ORDER BY p.code,CASE WHEN pr.role_type="PLAYER" THEN 0 ELSE 1 END,pr.slot_no');foreach($rq->fetchAll()as$r)$rolesByPlot[$r['code']][]=$r;}catch(Throwable$e){$error=($error??'').(($error??'')?' | ':'').$e->getMessage();}
