d:#f8fafc}.meta{font-size:12px;padding:10px 12px;border-bottom:1px solid #e5e7eb}.entry{padding:10px 12px;border-bottom:1px solid #eef2f7;font-size:12px;line-height:1.45;white-space:pre-line}.entry strong{display:block;font-size:11px;text-transform:uppercase;letter-spacing:.04em;color:#64748b;margin-bottom:4px}.world .entry{background:#fcfcfd}.factor{display:flex;justify-content:space-between;gap:8px;margin:3px 0}.muted{color:#64748b}.error{background:#fee2e2;color:#991b1b;padding:10px 14px}.phase{font-weight:700}.stats{margin-top:8px;padding-top:8px;border-top:1px dashed #d7dce4}.stat{display:flex;justify-content:space-between;gap:6px}.private{background:#fff7ed;border-left:3px solid #f59e0b;padding:8px;margin-top:8px}.private strong{display:block;margin-bottom:6px}.slot{font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:#64748b}.empty{padding:18px;color:#64748b;font-size:12px}.decision{margin:10px;border:1px solid #7c3aed;background:#f5f3ff;border-radius:10px;padding:10px;font-size:12px}.decision h3{font-size:13px;margin:0 0 8px}.decision form{margin:6px 0}.decision button{width:100%;text-align:left;background:white}.deadline{font-size:10px;color:#6d28d9;margin-top:6px}.final-state{margin:12px;border:2px solid #0f766e;background:#f0fdfa;border-radius:10px;padding:10px;font-size:12px;line-height:1.5}.final-state h3{margin:0 0 8px;font-size:13px;color:#115e59}.final-state-row{margin:5px 0}.changed{font-weight:700;color:#115e59}.unchanged{color:#64748b;font-size:10px}.final-state .stats{margin-top:8px;padding-top:8px;border-top:1px dashed #99d5cc}</style></head><body>
