<header><div class="top"><div class="brand">Toinky Story Engine Lab</div></div></header><main class="setup"><h1>New Simulation</h1><p>One shared reality. Different personal stories.</p><form method="post"><input type="hidden" name="action" value="create"><label>Story<br><select name="plot_code" required><?php foreach($plots as$p): ?><option value="<?=e($p['code'])?>"><?=e($p['title'])?> — <?=e($p['genre'])?></option><?php endforeach; ?></select></label><div id="controller-fields" class="controller-list"></div><?php if($plots): ?><div class="story-note"><?=count($plots)?> active <?=count($plots)===1?'story':'stories'?> available. Choose who is controlled by a person and who acts through AI.</div><?php else: ?><div class="story-note">No active stories are available. Check that the latest database migration has run.</div><?php endif; ?><br><label>Duration<br><select name="duration_seconds"><option value="300">5 minutes</option><option value="900">15 minutes</option></select></label><br><br><button <?=!$plots?'disabled':''?>>Create Simulation</button></form></main><script>
const rolesByPlot=<?=json_encode($rolesByPlot,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;
const plotSelect=document.querySelector('select[name="plot_code"]'),box=document.getElementById('controller-fields');
function renderControllers(){box.innerHTML='';(rolesByPlot[plotSelect.value]||[]).forEach(role=>{const row=document.createElement('label');row.className='controller-row';const defaultControl=role.role_type==='NPC'?'AI':'HUMAN';row.innerHTML='<span><b>'+role.name+'</b><br><small>'+role.role_type+' '+role.slot_no+'</small></span><select name="controllers['+role.role_code+']"><option value="HUMAN"'+(defaultControl==='HUMAN'?' selected':'')+'>Human</option><option value="AI"'+(defaultControl==='AI'?' selected':'')+'>AI</option></select>';box.appendChild(row);});}
plotSelect.addEventListener('change',renderControllers);renderControllers();
</script>
