<header><div class="top"><div><div class="brand">Toinky Story Engine Lab</div><div style="font-size:12px;color:#cbd5e1"><?=e($sim['title'])?> · <?=e($sim['genre'])?> · <?=e($sim['setting_name'])?></div></div><div class="controls"><span class="phase"><?=e($sim['current_phase'])?></span><span><?=gmdate('i:s',(int)$sim['elapsed_seconds'])?> / <?=gmdate('i:s',(int)$sim['duration_seconds'])?></span><?php if($sim['status']==='READY'): ?><form method="post"><input type="hidden" name="action" value="start"><input type="hidden" name="simulation_id" value="<?=$sid?>"><button>Start</button></form><?php elseif($sim['status']==='RUNNING'): ?><form method="post"><input type="hidden" name="action" value="advance"><input type="hidden" name="simulation_id" value="<?=$sid?>"><input type="hidden" name="seconds" value="30"><button>+30s</button></form><form method="post"><input type="hidden" name="action" value="advance"><input type="hidden" name="simulation_id" value="<?=$sid?>"><input type="hidden" name="seconds" value="60"><button>+60s</button></form><?php endif; ?><a class="button-link" href="?">New Simulation</a></div></div></header>
