$outcomeParts=[];$aiAudit=[];$decisionAudit=[];$factorAudit=[];$integrityWarnings=[];
try{$oq=db()->prepare('SELECT label_text,source_type,source_key FROM plot_outcome_dimensions WHERE plot_id=? AND active=1 ORDER BY sort_order,outcome_dimension_id');$oq->execute([$sim['plot_id']]);foreach($oq->fetchAll()as$d){if($d['source_type']==='FACTOR'){$v=null;foreach($x['factors']as$f)if($f['factor_code']===$d['source_key']){$n=(int)$f['current_value'];$v=$n<35?'LOW':($n<65?'MID':'HIGH');break;}}else{$s=GenericStateService::getByKey($sid,(string)$d['source_key']);$v=$s['exists']?strtoupper((string)$s['value']):'UNKNOWN';}$outcomeParts[]=trim($d['label_text'].' '.$v);}
$aq=db()->prepare('SELECT ai.*,c.name FROM ai_reasoner_interactions ai LEFT JOIN characters c ON c.character_id=ai.character_id WHERE ai.simulation_id=? ORDER BY ai.ai_interaction_id');$aq->execute([$sid]);$aiAudit=$aq->fetchAll();
$dq=db()->prepare('SELECT d.opens_at_second,d.status,d.chosen_option_code,d.resolved_text,c.name FROM decisions d JOIN characters c ON c.character_id=d.character_id WHERE d.simulation_id=? ORDER BY d.opens_at_second,d.decision_id');$dq->execute([$sid]);$decisionAudit=$dq->fetchAll();
$fq=db()->prepare('SELECT h.*,f.label FROM simulation_factor_history h LEFT JOIN simulation_factors f ON f.simulation_id=h.simulation_id AND f.factor_code=h.factor_code WHERE h.simulation_id=? ORDER BY h.event_second,h.factor_history_id');$fq->execute([$sid]);$factorAudit=$fq->fetchAll();
$irq=db()->prepare('SELECT r.integrity_rule_id,r.message_text FROM plot_integrity_rules r WHERE r.plot_id=? AND r.active=1 ORDER BY r.priority,r.integrity_rule_id');$irq->execute([$sim['plot_id']]);foreach($irq->fetchAll()as$rule){$cq=db()->prepare('SELECT source_type,source_key,operator,compare_value FROM plot_integrity_rule_conditions WHERE integrity_rule_id=? ORDER BY sort_order,integrity_rule_condition_id');$cq->execute([$rule['integrity_rule_id']]);$match=true;foreach($cq->fetchAll()as$condition){$key=$condition['source_type']==='FACTOR'?'FACTOR:'.$condition['source_key']:$condition['source_key'];if(!GenericStateService::conditionPasses($sid,(string)$key,(string)$condition['operator'],$condition['compare_value'])){$match=false;break;}}if($match)$integrityWarnings[]=$rule['message_text'];}}catch(Throwable$ignored){}
?>
